#!/usr/bin/env node
// roles/<agent>.md and the enabled plugins' plugins/<plugin>/roles/<agent>.md → src/roles.gen.ts, checked against the
// role shape (src/role-format.ts). Runs before check, test and deploy, like bundle-skills.mjs. The generated file is
// committed and never edited.
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parseRole } from "../src/role-format.ts";
import { enabledPlugins, ROOT } from "./plugins.mjs";

const DIRS = [join(ROOT, "roles"), ...(await enabledPlugins()).map((p) => join(p.dir, "roles")).filter(existsSync)];
const roles = {};
const problems = [];
for (const [DIR, f] of DIRS.flatMap((dir) => readdirSync(dir).filter((f) => f.endsWith(".md")).sort().map((f) => [dir, f]))) {
	const text = readFileSync(join(DIR, f), "utf8").trim();
	const parsed = parseRole(text);
	if (typeof parsed === "string") problems.push(`${f}: ${parsed}`);
	else if (roles[f.slice(0, -3)]) problems.push(`${f}: two role files for ${f.slice(0, -3)}`);
	else roles[f.slice(0, -3)] = text;
}
if (problems.length) {
	console.error(`Roles not bundled:\n${problems.join("\n")}`);
	process.exit(1);
}
writeFileSync(
	join(ROOT, "src", "roles.gen.ts"),
	`// Generated by scripts/bundle-roles.mjs from roles/. Do not edit: edit the role files.\n\nexport const ROLES: Record<string, string> = ${JSON.stringify(roles, null, "\t")};\n`,
);
